import { escHTML, escURL } from '@ntgovernment/squiz-factory/utils/xss';
import { componentAttrs } from "../_utils/component.helper";

const VALID_POSITIONS = new Set(['Left', 'Right']);
const VALID_BACKGROUNDS = new Set(['White', 'Gray']);

export default {
  async main(input = {}, info = {}) {
    const {
      image = '',
      imagePosition = 'Right',
      background = 'White',
      border = true,
      title = '',
      body = '',
      primaryButton = {},
      secondaryButton = {},
    } = input;

    const safePosition = VALID_POSITIONS.has(imagePosition) ? imagePosition : 'Right';
    const safeBackground = VALID_BACKGROUNDS.has(background) ? background : 'White';

    const resolvedImage = resolveImage(await resolveAsset(image, info.fns));

    const imageHtml = resolvedImage
      ? `<img class="featured-content__image" src="${escURL(resolvedImage.url)}" alt="${escHTML(resolvedImage.alt)}" loading="lazy" />`
      : '';

    const bodyHtml = body
      ? `<div class="featured-content__body" data-sq-field="body">${body}</div>`
      : '';

    const buttonsHtml = renderButtons(primaryButton, secondaryButton);

    return /*html*/`
<div ${componentAttrs("featured-content", input)} data-position="${escHTML(safePosition)}" data-background="${escHTML(safeBackground)}" data-border="${border ? 'true' : 'false'}">
  <div class="featured-content__media">
    ${imageHtml}
  </div>
  <div class="featured-content__text">
    ${title ? `<h2 class="featured-content__title" data-sq-field="title">${escHTML(title)}</h2>` : ''}
    ${bodyHtml}
    ${buttonsHtml}
  </div>
</div>
`;
  },
};

/**
 * fns.resolveUri wraps its result in a { ok, data } envelope -- confirmed
 * against a live Squiz DXP backend (see card.spec.md assumption 4, the same
 * mechanism reused here).
 */
async function resolveAsset(uri, fns) {
  if (!uri || typeof fns?.resolveUri !== 'function') return null;
  try {
    const result = await fns.resolveUri(uri);
    return unwrapResolved(result);
  } catch {
    return null;
  }
}

function unwrapResolved(result) {
  if (!result || typeof result !== 'object') return null;
  if ('data' in result) return result.data ?? null;
  return result;
}

/**
 * Per the real SquizImage schema (confirmed via image-gallery's own
 * resolveImage): imageVariations.original is a single object, not an
 * array. Falls back to a generic asset shape (plain url/name) if the
 * resolved value isn't SquizImage-shaped -- see featured-content.spec.md
 * assumption 1.
 */
function resolveImage(asset) {
  if (!asset) return null;
  const original = asset.imageVariations?.original || {};
  if (original.url) {
    return { url: original.url, alt: asset.alt || asset.name || '' };
  }
  const url = asset.url || (Array.isArray(asset.urls) ? asset.urls[0] : '') || '';
  return url ? { url, alt: asset.alt || asset.name || '' } : null;
}

/**
 * Renders both buttons side by side, omitting the wrapper entirely if
 * neither has both text and a resolvable link -- see renderButton().
 */
function renderButtons(primaryButton, secondaryButton) {
  const primaryHtml = renderButton(primaryButton, 'button featured-content__button');
  const secondaryHtml = renderButton(secondaryButton, 'button button-secondary featured-content__button');
  if (!primaryHtml && !secondaryHtml) return '';
  return `<div class="featured-content__actions">${primaryHtml}${secondaryHtml}</div>`;
}

/**
 * A button only renders once it has both its own `text` and a resolvable
 * `link` -- text alone with no destination would be a dead button. This is
 * how the secondary button (blank text by default) stays hidden until an
 * editor fills it in.
 */
function renderButton(button, className) {
  const text = button?.text || '';
  const resolvedLink = resolveLink(button?.link);
  if (!text || !resolvedLink) return '';
  return `<a class="${className}" href="${escURL(resolvedLink.url)}"${targetAttrs(resolvedLink.target)}>${escHTML(text)}</a>`;
}

/**
 * A SquizLink input resolves to a plain string (bare URL) or a
 * { text, url, target } object at the input level already -- no
 * fns.resolveUri() round-trip needed, unlike the `image` field (which is
 * `format: matrix-asset-uri`, a bare URI string that does need resolving).
 * Same pattern as quick-exit's own resolveLink(). This component ignores
 * `link.text` entirely: each button's own dedicated `text` field is the
 * label, not whatever text the link picker itself carries.
 */
function resolveLink(link) {
  if (!link) return null;
  if (typeof link === 'string') return { url: link, target: '_self' };
  if (typeof link === 'object' && link.url) return { url: link.url, target: link.target || '_self' };
  return null;
}

function targetAttrs(target) {
  return target && target !== '_self' ? ` target="${escHTML(target)}" rel="noopener noreferrer"` : '';
}
